const input = $json.body ?? $json;
const title = String(input.title ?? '').trim();
const description = String(input.description ?? '').trim();
if (title.length < 8 || title.length > 120) throw new Error('Заголовок должен содержать от 8 до 120 символов');
if (description.length < 30 || description.length > 1000) throw new Error('Описание должно содержать от 30 до 1000 символов');
return [{ json: { title, body: description, repository: 'YanDechart/ITMOv2' } }];

const request = $('Validate Request').first().json;
const raw = $json.output ?? $json;
const confidence = Math.max(0, Math.min(1, Number(raw.confidence) || 0));
const allowed = ['bug', 'task', 'feature'];
const candidate = String(raw.type ?? 'unknown').toLowerCase();
const type = confidence >= 0.8 && allowed.includes(candidate) ? candidate : 'needs-triage';
const priority = type === 'bug' && confidence >= 0.9 ? 'Высокий' : type === 'task' || type === 'needs-triage' ? 'Низкий' : 'Средний';
const recommendations = {
  bug: 'Воспроизвести ошибку, назначить ответственного и добавить регрессионный тест.',
  task: 'Уточнить критерии готовности и добавить задачу в ближайший спринт.',
  feature: 'Проверить пользовательскую ценность, описать acceptance criteria и оценить реализацию.',
  'needs-triage': 'Запросить недостающие детали и провести ручной разбор обращения.'
};
const labels = { bug: 'ошибка', task: 'задача', feature: 'новая возможность', 'needs-triage': 'обращение требует ручного разбора' };
return [{ json: {
  type,
  confidence,
  priority,
  summary: `«${request.title}» — ${labels[type]}.`,
  recommendation: recommendations[type],
  repository: request.repository
} }];
